library(shiny)
library(shinydashboard)
library(DT)
library(readr)
library(dplyr)
library(ggplot2)
library(data.table)

allData <- as.data.frame(read_csv("allBaseballData.csv"))

playerChoices <- unique(allData$Customer)
yearChoices <- unique(allData$yearID)
metricChoices <- c("Metric_1","Metric_2","Metric_3","Metric_4","Metric_5","Metric_6","Metric_7","Metric_8","Metric_9","Metric_10")
teamChoices <- unique(allData$City)


server <- function(input, output){
  
  teamData <- reactive({
    
    filteredData <- subset(allData, City == input$teamSelect)
    
    final <- data.table(filteredData)[,list(Metric_1 = sum(Metric_1),
                                            Metric_2 = sum(Metric_2),
                                            Metric_3 = sum(Metric_3),
                                            Metric_4 = sum(Metric_4),
                                            Metric_5 = sum(Metric_5),
                                            Metric_6 = sum(Metric_6),
                                            Metric_7 = sum(Metric_7),
                                            Metric_8 = sum(Metric_8),
                                            Metric_9 = sum(Metric_9),
                                            Metric_10 = sum(Metric_10)),
                                      by = list(City, yearID)]
    
    return(final)
    
  })
  
  yearData <- reactive({
    
    filteredData <- subset(allData, yearID == input$year)
    
    # final <- filteredData[order(filteredData[input$metricSelect], decreasing = T), ]
    final <- filteredData[do.call(order, c(filteredData[input$metricSelect], decreasing=TRUE)), ]
    final2 <- final[1:10,]
    
    final2$Customer <- factor(final2$Customer,levels = unique(final2$Customer))
    
    return(final2)
    
  })
  
  playerData <- reactive({
    
    filteredData <- subset(allData, Customer == input$playerSelect)
    
    return(filteredData)
    
  })
  
  playerCareerData <- reactive({
    
    data <- playerData()
    
    careerData <- data.table(data)[,list(Metric_1 = sum(Metric_1),
                                         Metric_2 = sum(Metric_2),
                                         Metric_3 = sum(Metric_3),
                                         Metric_4 = sum(Metric_4),
                                         Metric_5 = sum(Metric_5),
                                         Metric_6 = sum(Metric_6),
                                         Metric_7 = sum(Metric_7),
                                         Metric_8 = sum(Metric_8),
                                         Metric_9 = sum(Metric_9),
                                         Metric_10 = sum(Metric_10)),
                                   by = list(Customer)]
    
    return(careerData)
    
  })
  
  output$careerDataPlayer <- renderDT({
    
    data <- playerCareerData()
    
    datatable(data, options = list(pageLength = nrow(data)))
    
  })
  
  output$yearlyDataPlayer <- renderDT({
    
    data <- playerData()
    
    datatable(data, options = list(pageLength = nrow(data)))
    
  })
  
  output$yearPlotPlayer <- renderPlot({
    
    plot <- ggplot(playerData(), aes_string(x = "yearID", y = input$metricSelect)) 
    plot <- plot + geom_col(fill = "blue") 
    plot <- plot + ggtitle(paste0(input$metricSelect, " Per Year For ", input$playerSelect))
    plot
    
  })
  
  output$teamData <- renderDT({
    
    data <- teamData()
    
    datatable(data, options = list(pageLength = nrow(data)))
    
  })
  
  output$yearLeaderPlot <- renderPlot({
    
    plot <- ggplot(yearData())
    plot <- plot + geom_col(aes_string(x = "Customer", y = input$metricSelect), fill = "blue")
    plot <- plot + ggtitle(paste0(input$metricSelect, " Leaders For the Year ", input$year))
    plot
    
  })
  
  
}
ui <- dashboardPage(
  dashboardHeader(title = "Customer Profiling"),
  dashboardSidebar(
    sidebarMenu(
      menuItem(text = "Customer Data", 
               startExpanded = TRUE,
               menuSubItem(text = "Data", tabName = "playerData"),
               menuSubItem(text = "Plots", tabName = "playerPlot")
      ),
      menuItem(text = "Data Per City/Year", tabName = "dataPerTeamYear"),
      menuItem(text = "Yearly Customer", tabName = "yearlyleaders"),
      selectInput(inputId = "playerSelect", label = "Select a Customer:", choices = playerChoices, selected = "Barry Bonds"),
      selectInput("metricSelect", label = "Select which Metric to display:", choices = metricChoices, selected = "HR"),
      selectInput("teamSelect", label = "Select which City to view", choices = teamChoices, selected = "New York Yankees"),
      selectInput("year", label = "Select which Year to view", choices = yearChoices, selected = 2015)
    )
  ),
  dashboardBody(
    tags$head(tags$style(HTML(
      '.myClass { 
        font-size: 20px;
        line-height: 50px;
        text-align: left;
        font-family: "Helvetica Neue",Helvetica,Arial,sans-serif;
        padding: 0 15px;
        overflow: hidden;
        color: white;
      }
    '))),
    tags$script(HTML('
      $(document).ready(function() {
        $("header").find("nav").append(\'<span class="myClass"> Author: Fabián Suárez Ardila </span>\');
      })
     ')),
    
    tabItems(
      tabItem(tabName = "playerData",
              DTOutput(outputId = "careerDataPlayer"),
              DTOutput(outputId = "yearlyDataPlayer")
      ),
      tabItem(tabName = "playerPlot",
              plotOutput("yearPlotPlayer")
      ),
      tabItem(tabName = "dataPerTeamYear",
              DTOutput("teamData")),
      tabItem(tabName = "yearlyleaders",
              plotOutput("yearLeaderPlot"))
    )
  )
)

shinyApp(ui, server)
